defineEmits<{select:[row:HeadRow];previous:[];next:[]}>()
</script>
<template><div v-if="data"><p class="md-muted">查询时间：{{time(data.queriedAt)}} · 每行按股票、来源及价格口径展示</p><div class="md-table" role="region" aria-label="行情覆盖列表" tabindex="0"><table><thead><tr><th>股票</th><th>来源与口径</th><th>当前状态</th><th>覆盖日期</th><th>检查与发布时间</th><th>质量与最近更新</th><th>操作</th></tr></thead><tbody><tr v-for="row in data.items" :key="row.instrumentId+':'+row.provider+':'+row.priceBasis"><td>{{row.displayName}}<br>{{row.instrumentId}}<br><small>{{row.nameVerified?'名称已核验':'名称未核验'}} · {{row.listingStatus}}</small></td><td>{{row.provider||'尚无来源头'}}<br>{{label(row.priceBasis)}}</td><td>{{label(row.headState)}}<br><small v-if="row.headRevision">头修订：{{row.headRevision}}</small></td><td>{{row.coverageStart||'暂无'}} ～ {{row.coverageEnd||'暂无'}}</td><td>检查：{{time(row.checkedAt)}}<br>取数：{{time(row.fetchedAt)}}<br>发布：{{time(row.publishedAt)}}</td><td>{{label(row.quality)}}<p v-if="row.lastErrorCode">最近更新：{{label(row.lastErrorCode)}}<br><small>当前头状态与最近更新结果分别记录。</small></p></td><td><button type="button" data-test="open-stock" @click="$emit('select',row)">查看版本与更新操作<span class="sr-only">：{{row.instrumentId}}</span></button></td></tr></tbody></table></div><p v-if="!data.items.length">没有符合条件的已登记股票。</p><div class="md-actions"><button type="button" :disabled="busy||data.query.page<=1" @click="$emit('previous')">上一页</button><span>第 {{data.query.page}} 页</span><button type="button" data-test="head-next" :disabled="busy||!data.hasMore" @click="$emit('next')">下一页</button></div></div></template>
